/**
 * Pull command handler
 */
import { parsePullArgs, pullCommand } from "./command.js";
import { showHeader } from "../../utils/index.js";
import { parseArgsOrThrow } from "../../shared/args.js";
export async function handlePullCommand(args) {
    showHeader();
    await pullCommand(parseArgsOrThrow(parsePullArgs, "pull", args));
}
